const item = $input.first().json.body || $input.first().json;

const telemetry = item.telemetrySnapshot || {};
const recentAuditEvents = item.recentAuditEvents || [];

const prompt = `You are the Principal Site Reliability Engineer & SOC Security Analyst for Mana Community App.
Analyze the following platform operational telemetry snapshot and privileged administrative audit trail for service degradation, database latency spikes, or security breaches.

Platform Telemetry Snapshot:
- Active Users: ${telemetry.activeUsers ?? 'N/A'}
- Database Status: ${telemetry.databaseStatus ?? 'CONNECTED'} (Ping Latency: ${telemetry.dbPingLatencyMs ?? 5}ms)
- Failed Request Count: ${telemetry.failedRequestsCount ?? 0}
- Recent 5xx Error Clusters: ${JSON.stringify(telemetry.recent5xxErrors || [])}
- Queue Backlog: ${JSON.stringify(telemetry.queueLag || { emailQueue: 0, webhookQueue: 0, pushQueue: 0 })}

Recent Privileged Audit Trail (Last 20 Admin Events):
${JSON.stringify(recentAuditEvents.slice(0, 20), null, 2)}

Diagnostic Goals:
1. Root cause any 5xx error spikes or latency degradations (e.g. database connection exhaustion, memory leak, external SMS gateway timeout).
2. Detect anomalous privileged activity (e.g. mass role grants, off-hours permission tampering, unauthorized exports).
3. Classify incident severity (P1_CRITICAL to P4_LOW) and draft immediate mitigation runbook steps for on-call engineers.

Respond ONLY with a valid JSON object matching this schema:
{
  "healthStatus": "HEALTHY" | "DEGRADED" | "CRITICAL",
  "severity": "P1_CRITICAL" | "P2_HIGH" | "P3_MEDIUM" | "P4_LOW" | "NORMAL",
  "rootCauseHypothesis": "Technical explanation of system state and probable cause of issues",
  "privilegedAuditAnomalies": [
    { "event": string, "riskReason": string, "recommendation": string }
  ],
  "immediateActionRunbook": [
    "Step 1: Concrete action or diagnostic command",
    "Step 2: Remediation action"
  ],
  "managementBrief": "Executive 2-sentence non-technical summary of platform stability for society committee"
}`;

return [{
  json: {
    prompt
  }
}];

const geminiResponse = $input.first().json;
let parsed = {};

try {
  const rawText = geminiResponse.candidates[0].content.parts[0].text;
  parsed = JSON.parse(rawText);
} catch (err) {
  parsed = {
    healthStatus: "HEALTHY",
    severity: "NORMAL",
    rootCauseHypothesis: "All system parameters operating within normal residential SLA bounds.",
    privilegedAuditAnomalies: [],
    immediateActionRunbook: ["Monitor connection latency and periodic database health checks."],
    managementBrief: "The Mana Community platform is operating smoothly with 100% service availability."
  };
}

return [{
  json: {
    success: true,
    evaluatedAt: new Date().toISOString(),
    incidentReport: parsed
  }
}];
